export const QUESTIONS = [{"id":"1445dBVC548wLduKB6kf","type":"subjective","question":"An atom has 7 protons, 7 neutrons, and 7 electrons. This element is identified as ____.","options":null,"answerIndex":null,"answer":"Nitrogen","explanation":["The identity of an element is entirely determined by its proton number; 7 protons corresponds to Nitrogen."],"hint":"","image":null,"video":"https://youtu.be/rz4Dd1I_fX0?si=Ir4GLYwCuCjX4cVu","videoScope":"set","topic":"Elements of the Periodic Table","classLevel":"grade10","scheme":"practice","subject":"chemistry","subjectLabel":"Chemistry","grade":"Grade 10"},{"id":"783GqRZkkKmxwFSm9cBi","type":"subjective","question":"Elements located in the large middle block of the periodic table (Groups 3 to 12), such as Iron, Copper, and Gold, are classified as ____ metals.","options":null,"answerIndex":null,"answer":"transition","explanation":["Transition metals bridge the highly reactive s-block metals and the p-block non-metals/metalloids."],"hint":"","image":null,"video":"https://youtu.be/rz4Dd1I_fX0?si=Ir4GLYwCuCjX4cVu","videoScope":"set","topic":"Elements of the Periodic Table","classLevel":"grade10","scheme":"practice","subject":"chemistry","subjectLabel":"Chemistry","grade":"Grade 10"},{"id":"8QeYsUpBdr3ROyJt6Sm9","type":"subjective","question":"The element Beryllium has an atomic number of 4, meaning it contains exactly ____ protons in its nucleus.","options":null,"answerIndex":null,"answer":"4","explanation":["The atomic number always corresponds directly to the total count of protons inside an atom's nucleus."],"hint":"","image":null,"video":"https://youtu.be/rz4Dd1I_fX0?si=Ir4GLYwCuCjX4cVu","videoScope":"set","topic":"Elements of the Periodic Table","classLevel":"grade10","scheme":"practice","subject":"chemistry","subjectLabel":"Chemistry","grade":"Grade 10"},{"id":"9WOpaipNnqMbvQlrAuka","type":"short","question":"Which transition metal, famously represented by the symbol Au, is referenced in the lyric 'gold to make you rich'?","options":null,"answerIndex":null,"answer":"Gold","explanation":["Gold has the symbol Au, which stems from its classical Latin name Aurum."],"hint":"","image":null,"video":"https://youtu.be/rz4Dd1I_fX0?si=Ir4GLYwCuCjX4cVu","videoScope":"set","topic":"Elements of the Periodic Table","classLevel":"grade10","scheme":"practice","subject":"chemistry","subjectLabel":"Chemistry","grade":"Grade 10"},{"id":"9XrMv199YZsmGzheTNd8","type":"subjective","question":"The chemical element referenced in the song as being responsible for 'salty times' is ____.","options":null,"answerIndex":null,"answer":"Sodium","explanation":["Sodium (Na) combines with chlorine to form sodium chloride (( \text{NaCl} )), which is common table salt."],"hint":"","image":null,"video":"https://youtu.be/rz4Dd1I_fX0?si=Ir4GLYwCuCjX4cVu","videoScope":"set","topic":"Elements of the Periodic Table","classLevel":"grade10","scheme":"practice","subject":"chemistry","subjectLabel":"Chemistry","grade":"Grade 10"},{"id":"A2t0CkKDUKgFR27AQNst","type":"polar","question":"Metalloids are found primarily on the far left side of the periodic table, mixed completely within the alkali metal family.","options":["True","False"],"answerIndex":1,"answer":null,"explanation":["Metalloids sit along a diagonal line between metals on the left/middle and non-metals on the right."],"hint":"Look toward the diagonal boundary line separating metals and non-metals.","image":null,"video":"https://youtu.be/rz4Dd1I_fX0?si=Ir4GLYwCuCjX4cVu","videoScope":"set","topic":"Elements of the Periodic Table","classLevel":"grade10","scheme":"practice","subject":"chemistry","subjectLabel":"Chemistry","grade":"Grade 10"},{"id":"Gy4ahGndMCfqaOTXHVrE","type":"theory","question":"Predict the chemical formula of the compound formed when Calcium (Group 2) reacts with Fluorine (Group 17), and explain your reasoning based on valence electrons.","options":null,"answerIndex":null,"answer":"The formula is ( \text{CaF}_2 ). Calcium has 2 valence electrons to lose to become ( \text{Ca}^{2+} ), while each Fluorine atom needs to gain 1 electron to become ( \text{F}^- ). Thus, two fluorine atoms are required for every calcium atom to balance the charges.","explanation":["Ionic charge neutrality dictates that one ( \text{Ca}^{2+} ) balances two ( \text{F}^- ) ions, yielding ( \text{CaF}_2 )."],"hint":"","image":null,"video":"https://youtu.be/rz4Dd1I_fX0?si=Ir4GLYwCuCjX4cVu","videoScope":"set","topic":"Elements of the Periodic Table","classLevel":"grade10","scheme":"practice","subject":"chemistry","subjectLabel":"Chemistry","grade":"Grade 10"},{"id":"HRBiEXrwwzIL0jyG8QLN","type":"theory","question":"Describe what happens to the atomic radius of elements as you move left to right across Period 3 (from Sodium to Argon) and explain why this pattern occurs.","options":null,"answerIndex":null,"answer":"The atomic radius decreases. As you move across the period, protons are added to the nucleus, increasing the positive nuclear charge. This stronger positive charge pulls the same valence electron shell closer to the nucleus.","explanation":["Increased effective nuclear charge overrides the minimal shielding increase across a single period, contracting the atom."],"hint":"","image":null,"video":"https://youtu.be/rz4Dd1I_fX0?si=Ir4GLYwCuCjX4cVu","videoScope":"set","topic":"Elements of the Periodic Table","classLevel":"grade10","scheme":"practice","subject":"chemistry","subjectLabel":"Chemistry","grade":"Grade 10"},{"id":"Ks1fP9B6DkFEsdXnnGpc","type":"theory","question":"A student states that Chlorine is more reactive than Argon. Evaluate whether this statement is true or false, providing a full electronic justification.","options":null,"answerIndex":null,"answer":"The statement is true. Chlorine has 7 valence electrons and needs only 1 more electron to fill its shell, making it highly reactive to gain that electron. Argon already has a completely filled valence shell (8 electrons), making it exceptionally stable and chemically inert.","explanation":["Halogens are one electron short of an octet, whereas noble gases have a completed stable octet configuration."],"hint":"","image":null,"video":"https://youtu.be/rz4Dd1I_fX0?si=Ir4GLYwCuCjX4cVu","videoScope":"set","topic":"Elements of the Periodic Table","classLevel":"grade10","scheme":"practice","subject":"chemistry","subjectLabel":"Chemistry","grade":"Grade 10"},{"id":"MERxSmmvRQ0OkVBdOo0W","type":"theory","question":"Explain why Helium behaves like a noble gas in Group 18 even though it only possesses 2 valence electrons instead of the usual 8.","options":null,"answerIndex":null,"answer":"Helium's valence electrons occupy the first electron shell (( n=1 )), which can hold a maximum of only 2 electrons. Because this first shell is completely full, Helium achieves maximum stability and behaves chemically like the other noble gases.","explanation":["A full valence shell imparts chemical stability, regardless of whether that max capacity is 2 or 8."],"hint":"","image":null,"video":"https://youtu.be/rz4Dd1I_fX0?si=Ir4GLYwCuCjX4cVu","videoScope":"set","topic":"Elements of the Periodic Table","classLevel":"grade10","scheme":"practice","subject":"chemistry","subjectLabel":"Chemistry","grade":"Grade 10"},{"id":"O4dAbDkhfkJXoEIq6b8z","type":"polar","question":"Silicon, mentioned right after aluminum in the periodic sequence, is classified as a metalloid rather than a pure metal or pure non-metal.","options":["True","False"],"answerIndex":0,"answer":null,"explanation":["Silicon shares intermediate properties of both metals and non-metals, which makes it a classic semiconductor metalloid."],"hint":"Consider its location on the staircase line of the periodic table.","image":null,"video":"https://youtu.be/rz4Dd1I_fX0?si=Ir4GLYwCuCjX4cVu","videoScope":"set","topic":"Elements of the Periodic Table","classLevel":"grade10","scheme":"practice","subject":"chemistry","subjectLabel":"Chemistry","grade":"Grade 10"},{"id":"OTo389HNOhC7D9F8KkOR","type":"subjective","question":"The modern periodic table organizes all known elements in ascending order of their atomic ____.","options":null,"answerIndex":null,"answer":"number","explanation":["Elements are arranged by atomic number, which is the number of protons in the nucleus of an atom."],"hint":"","image":null,"video":"https://youtu.be/rz4Dd1I_fX0?si=Ir4GLYwCuCjX4cVu","videoScope":"set","topic":"Elements of the Periodic Table","classLevel":"grade10","scheme":"practice","subject":"chemistry","subjectLabel":"Chemistry","grade":"Grade 10"},{"id":"QjC2URO5mX34NXGyRUxP","type":"objective","question":"A mystery element is found to be highly unreactive, a gas at room temperature, and has 8 valence electrons in its outer shell. Which family does it belong to?","options":["Noble Gases","Halogens","Alkali Metals","Transition Metals"],"answerIndex":0,"answer":null,"explanation":["Elements with a full valence octet are stable and belong to Group 18, the noble gases."],"hint":"Recall the stability of elements at the far right of the table.","image":null,"video":"https://youtu.be/rz4Dd1I_fX0?si=Ir4GLYwCuCjX4cVu","videoScope":"set","topic":"Elements of the Periodic Table","classLevel":"grade10","scheme":"practice","subject":"chemistry","subjectLabel":"Chemistry","grade":"Grade 10"},{"id":"VLcPYUFwbFyWr1pLGSxL","type":"short","question":"What lightweight gas is the very first element listed on the periodic table?","options":null,"answerIndex":null,"answer":"Hydrogen","explanation":["Hydrogen (( \text{H} )) is the simplest and first element, possessing an atomic number of 1."],"hint":"","image":null,"video":"https://youtu.be/rz4Dd1I_fX0?si=Ir4GLYwCuCjX4cVu","videoScope":"set","topic":"Elements of the Periodic Table","classLevel":"grade10","scheme":"practice","subject":"chemistry","subjectLabel":"Chemistry","grade":"Grade 10"},{"id":"Wrrk6AUcxDWZUKoe3jjk","type":"objective","question":"If a student wants to find a metal that is a liquid at room temperature to use in a thermometer simulation, which element from the song should they select?","options":["Mercury","Gallium","Gold","Silver"],"answerIndex":0,"answer":null,"explanation":["Mercury (( \text{Hg} )) remains liquid at standard ambient temperature and has historically been used in thermometers."],"hint":"The song mentions this element 'tells you when it's really cold'.","image":null,"video":"https://youtu.be/rz4Dd1I_fX0?si=Ir4GLYwCuCjX4cVu","videoScope":"set","topic":"Elements of the Periodic Table","classLevel":"grade10","scheme":"practice","subject":"chemistry","subjectLabel":"Chemistry","grade":"Grade 10"},{"id":"X8qlrFezk91yjyuBOcng","type":"theory","question":"Contrast the physical state and general appearance of non-metals on the right side of the periodic table with metals on the left side.","options":null,"answerIndex":null,"answer":"Metals are typically shiny, malleable, ductile solids at room temperature (except mercury). In contrast, non-metals exhibit a variety of states (gases, liquids, brittle solids), lack a metallic luster, and are poor conductors.","explanation":["Metals exhibit metallic bonding with delocalized electrons, whereas non-metals form covalent structures or exist as individual atoms/molecules."],"hint":"","image":null,"video":"https://youtu.be/rz4Dd1I_fX0?si=Ir4GLYwCuCjX4cVu","videoScope":"set","topic":"Elements of the Periodic Table","classLevel":"grade10","scheme":"practice","subject":"chemistry","subjectLabel":"Chemistry","grade":"Grade 10"},{"id":"XNjvENfxgwT6f7Tbb1hG","type":"polar","question":"Elements belonging to the same vertical group on the periodic table generally share similar chemical properties because they have the same number of valence electrons.","options":["True","False"],"answerIndex":0,"answer":null,"explanation":["The outer shell electron configuration determines how an element bonds, making group members behave analogously."],"hint":"Chemical behavior is dictated by outer shell electrons.","image":null,"video":"https://youtu.be/rz4Dd1I_fX0?si=Ir4GLYwCuCjX4cVu","videoScope":"set","topic":"Elements of the Periodic Table","classLevel":"grade10","scheme":"practice","subject":"chemistry","subjectLabel":"Chemistry","grade":"Grade 10"},{"id":"XOMRD6TnQBVVgQWByimN","type":"short","question":"Name the specific group of non-metals on the periodic table that are described as reacting 'aggressively' along with alkali metals.","options":null,"answerIndex":null,"answer":"Halogens","explanation":["The video notes that 'noble gases stable, halogens and alkali react aggressively'. Halogens are the highly reactive non-metals in Group 17."],"hint":"","image":null,"video":"https://youtu.be/rz4Dd1I_fX0?si=Ir4GLYwCuCjX4cVu","videoScope":"set","topic":"Elements of the Periodic Table","classLevel":"grade10","scheme":"practice","subject":"chemistry","subjectLabel":"Chemistry","grade":"Grade 10"},{"id":"YsT8BQyjoyvCYmeTvSbF","type":"objective","question":"Which element is noted in the song for keeping our bones and teeth strong?","options":["Calcium","Potassium","Scandium","Magnesium"],"answerIndex":0,"answer":null,"explanation":["The song pairs potassium and calcium together, noting that calcium is essential for skeletal strength."],"hint":"Think about dairy products and the lyrics 'so y'all go strong'.","image":null,"video":"https://youtu.be/rz4Dd1I_fX0?si=Ir4GLYwCuCjX4cVu","videoScope":"set","topic":"Elements of the Periodic Table","classLevel":"grade10","scheme":"practice","subject":"chemistry","subjectLabel":"Chemistry","grade":"Grade 10"},{"id":"ZiCKxcpDCJv1WGuOvqIY","type":"objective","question":"Why do elements in the same period have different chemical properties despite having the same number of electron shells?","options":["They have different numbers of valence electrons.","Their core inner electron shells vary drastically.","They all belong to the same vertical family group.","They possess identical electronegativity values."],"answerIndex":0,"answer":null,"explanation":["As you move across a period, each element gains another valence electron, altering how it bonds and reacts."],"hint":"Recall that chemical reactions involve outer shell interactions.","image":null,"video":"https://youtu.be/rz4Dd1I_fX0?si=Ir4GLYwCuCjX4cVu","videoScope":"set","topic":"Elements of the Periodic Table","classLevel":"grade10","scheme":"practice","subject":"chemistry","subjectLabel":"Chemistry","grade":"Grade 10"},{"id":"aEtGzERANVXhQt9M2YEx","type":"short","question":"Which element, representing atomic number 6, forms the structural backbone of all organic biochemistry and everywhere life?","options":null,"answerIndex":null,"answer":"Carbon","explanation":["Carbon is capable of forming four covalent bonds, allowing for complex long-chain molecules essential to living organisms."],"hint":"","image":null,"video":"https://youtu.be/rz4Dd1I_fX0?si=Ir4GLYwCuCjX4cVu","videoScope":"set","topic":"Elements of the Periodic Table","classLevel":"grade10","scheme":"practice","subject":"chemistry","subjectLabel":"Chemistry","grade":"Grade 10"},{"id":"agOVzeXW83ZjG03eObtj","type":"objective","question":"An element is shiny, malleable, conducts electricity efficiently, and forms a basic oxide when reacted with oxygen. Where is this element likely located?","options":["On the left side or center of the periodic table.","In the upper right corner with the gases.","Exclusively in Group 18.","Along the diagonal metalloid staircase."],"answerIndex":0,"answer":null,"explanation":["Metals are found on the left and center of the periodic table and generally form basic oxides."],"hint":"Consider the general properties of typical metallic elements.","image":null,"video":"https://youtu.be/rz4Dd1I_fX0?si=Ir4GLYwCuCjX4cVu","videoScope":"set","topic":"Elements of the Periodic Table","classLevel":"grade10","scheme":"practice","subject":"chemistry","subjectLabel":"Chemistry","grade":"Grade 10"},{"id":"eGlSvCLMh9NezlykjMLd","type":"objective","question":"According to periodic trends mentioned in the video, what happens to the electron configuration as you move from left to right across a single period?","options":["New outer shell electrons are sequentially added.","The total number of electron shells increases.","Electrons are removed from the innermost core shell.","The valency remains completely constant across the row."],"answerIndex":0,"answer":null,"explanation":["As stated in the video, moving to the right across a period means new outer shell electrons are added to the same main energy level."],"hint":"Think about what changes in the outermost energy level when moving from lithium towards neon.","image":null,"video":"https://youtu.be/rz4Dd1I_fX0?si=Ir4GLYwCuCjX4cVu","videoScope":"set","topic":"Elements of the Periodic Table","classLevel":"grade10","scheme":"practice","subject":"chemistry","subjectLabel":"Chemistry","grade":"Grade 10"},{"id":"ea9qbI6AssaXWBIm03jD","type":"polar","question":"As you move down a specific group or family in the periodic table, the total number of occupied electron shells decreases.","options":["True","False"],"answerIndex":1,"answer":null,"explanation":["Going down a group increases the principal quantum number, adding an entirely new electron shell for each row down."],"hint":"Think about going from Hydrogen to Lithium to Sodium.","image":null,"video":"https://youtu.be/rz4Dd1I_fX0?si=Ir4GLYwCuCjX4cVu","videoScope":"set","topic":"Elements of the Periodic Table","classLevel":"grade10","scheme":"practice","subject":"chemistry","subjectLabel":"Chemistry","grade":"Grade 10"},{"id":"gaovwSclGKK06tvT1SeK","type":"subjective","question":"As you move down Group 1 from Lithium to Cesium, the reactivity of the alkali metals ____.","options":null,"answerIndex":null,"answer":"increases","explanation":["Reactivity increases down Group 1 because the valence electron is further from the nucleus and easier to lose."],"hint":"","image":null,"video":"https://youtu.be/rz4Dd1I_fX0?si=Ir4GLYwCuCjX4cVu","videoScope":"set","topic":"Elements of the Periodic Table","classLevel":"grade10","scheme":"practice","subject":"chemistry","subjectLabel":"Chemistry","grade":"Grade 10"},{"id":"gvQ3GZCHrtSCzpc7QbFa","type":"short","question":"Which noble gas is lighter than air and used to inflate celebratory balloons?","options":null,"answerIndex":null,"answer":"Helium","explanation":["Helium (( \text{He} )) is less dense than air, causing balloons filled with it to float upward."],"hint":"","image":null,"video":"https://youtu.be/rz4Dd1I_fX0?si=Ir4GLYwCuCjX4cVu","videoScope":"set","topic":"Elements of the Periodic Table","classLevel":"grade10","scheme":"practice","subject":"chemistry","subjectLabel":"Chemistry","grade":"Grade 10"},{"id":"jPgwFlQW9k7FKvZTpEli","type":"subjective","question":"The gas that lights up commercial display signs and is explicitly mentioned in the song for this purpose is ____.","options":null,"answerIndex":null,"answer":"Neon","explanation":["Neon (( \text{Ne} )) is a noble gas that glows a bright reddish-orange color when an electric current passes through it."],"hint":"","image":null,"video":"https://youtu.be/rz4Dd1I_fX0?si=Ir4GLYwCuCjX4cVu","videoScope":"set","topic":"Elements of the Periodic Table","classLevel":"grade10","scheme":"practice","subject":"chemistry","subjectLabel":"Chemistry","grade":"Grade 10"},{"id":"kWeBMjqW4DLQj2kA64Jt","type":"subjective","question":"The element Sulfur belongs to Group 16. It has exactly ____ valence electrons in its outer shell.","options":null,"answerIndex":null,"answer":"6","explanation":["Group 16 elements (also known as chalcogens) possess six outer shell electrons."],"hint":"","image":null,"video":"https://youtu.be/rz4Dd1I_fX0?si=Ir4GLYwCuCjX4cVu","videoScope":"set","topic":"Elements of the Periodic Table","classLevel":"grade10","scheme":"practice","subject":"chemistry","subjectLabel":"Chemistry","grade":"Grade 10"},{"id":"mllZrea49ngwwQL4tNwp","type":"short","question":"What is the chemical symbol for Potassium, an alkali metal mentioned right before calcium?","options":null,"answerIndex":null,"answer":"K","explanation":["Potassium's symbol is K, derived from its Latin name Kalium."],"hint":"","image":null,"video":"https://youtu.be/rz4Dd1I_fX0?si=Ir4GLYwCuCjX4cVu","videoScope":"set","topic":"Elements of the Periodic Table","classLevel":"grade10","scheme":"practice","subject":"chemistry","subjectLabel":"Chemistry","grade":"Grade 10"},{"id":"mzUIJNVoy5V9wZlGgIjw","type":"short","question":"What is the name of the Group 17 halogen that is a yellowish-green toxic gas used to disinfect swimming pools?","options":null,"answerIndex":null,"answer":"Chlorine","explanation":["Chlorine (( \text{Cl} )) is a highly reactive halogen widely utilized as an effective sanitizing and bleaching agent."],"hint":"","image":null,"video":"https://youtu.be/rz4Dd1I_fX0?si=Ir4GLYwCuCjX4cVu","videoScope":"set","topic":"Elements of the Periodic Table","classLevel":"grade10","scheme":"practice","subject":"chemistry","subjectLabel":"Chemistry","grade":"Grade 10"},{"id":"ntAhGt74Oh0YCmu2pEWG","type":"polar","question":"Non-metals are generally excellent conductors of electricity and thermal energy.","options":["True","False"],"answerIndex":1,"answer":null,"explanation":["Non-metals are poor conductors due to the localization of their electrons, making them good electrical insulators."],"hint":"Think about materials used to insulate electrical wires.","image":null,"video":"https://youtu.be/rz4Dd1I_fX0?si=Ir4GLYwCuCjX4cVu","videoScope":"set","topic":"Elements of the Periodic Table","classLevel":"grade10","scheme":"practice","subject":"chemistry","subjectLabel":"Chemistry","grade":"Grade 10"},{"id":"oYqnTb1I5dmV9maLQmJc","type":"short","question":"What highly reactive gas has atomic number 9 and is noted in the song as 'pretty to eat' (often found in trace amounts in toothpaste)?","options":null,"answerIndex":null,"answer":"Fluorine","explanation":["Fluorine (( \text{F} )) compounds (fluorides) are widely used in oral healthcare products to protect teeth."],"hint":"","image":null,"video":"https://youtu.be/rz4Dd1I_fX0?si=Ir4GLYwCuCjX4cVu","videoScope":"set","topic":"Elements of the Periodic Table","classLevel":"grade10","scheme":"practice","subject":"chemistry","subjectLabel":"Chemistry","grade":"Grade 10"},{"id":"osIeMbwLeERpWIxwT9Or","type":"polar","question":"Noble gases are characterized by extreme chemical stability and do not readily react with other elements.","options":["True","False"],"answerIndex":0,"answer":null,"explanation":["Noble gases have a full outer shell of valence electrons, making them chemically stable and unreactive under standard conditions."],"hint":"Recall how noble gases like Helium and Neon are described in the song.","image":null,"video":"https://youtu.be/rz4Dd1I_fX0?si=Ir4GLYwCuCjX4cVu","videoScope":"set","topic":"Elements of the Periodic Table","classLevel":"grade10","scheme":"practice","subject":"chemistry","subjectLabel":"Chemistry","grade":"Grade 10"},{"id":"ovRgTBmzyw39XWiTZBMY","type":"objective","question":"An element has an atomic number of 11. Based on your understanding of the periodic table, which group does this element belong to?","options":["Group 1 (Alkali Metals)","Group 2 (Alkaline Earth Metals)","Group 17 (Halogens)","Group 18 (Noble Gases)"],"answerIndex":0,"answer":null,"explanation":["An atomic number of 11 corresponds to Sodium (( \text{Na} )), which has a configuration of ( 2, 8, 1 ), placing it squarely in Group 1."],"hint":"Write out the electron configuration using ( 2, 8, 1 ) as a guide.","image":null,"video":"https://youtu.be/rz4Dd1I_fX0?si=Ir4GLYwCuCjX4cVu","videoScope":"set","topic":"Elements of the Periodic Table","classLevel":"grade10","scheme":"practice","subject":"chemistry","subjectLabel":"Chemistry","grade":"Grade 10"},{"id":"pW9aeuZzUuqNc5zvhSV0","type":"objective","question":"Which pair of elements are both categorized as transition metals based on their position in the middle block of the table?","options":["Iron and Nickel","Sodium and Potassium","Carbon and Oxygen","Helium and Neon"],"answerIndex":0,"answer":null,"explanation":["Iron and Nickel are located in the d-block (Groups 3-12) and act as typical transition metals."],"hint":"Look for metals used frequently in structural alloys and coins.","image":null,"video":"https://youtu.be/rz4Dd1I_fX0?si=Ir4GLYwCuCjX4cVu","videoScope":"set","topic":"Elements of the Periodic Table","classLevel":"grade10","scheme":"practice","subject":"chemistry","subjectLabel":"Chemistry","grade":"Grade 10"},{"id":"qYAGurvsrRlL3qqoJGnI","type":"objective","question":"Which element from Period 2 has the lowest first ionization energy?","options":["Lithium","Carbon","Oxygen","Neon"],"answerIndex":0,"answer":null,"explanation":["Lithium is on the far left of Period 2. It has a large atomic radius and only one valence electron, making it easy to remove."],"hint":"Ionization energy generally increases from left to right across a period.","image":null,"video":"https://youtu.be/rz4Dd1I_fX0?si=Ir4GLYwCuCjX4cVu","videoScope":"set","topic":"Elements of the Periodic Table","classLevel":"grade10","scheme":"practice","subject":"chemistry","subjectLabel":"Chemistry","grade":"Grade 10"},{"id":"qofhDtTLLSOCu33PBpO4","type":"objective","question":"Which of the following elements is a non-metal that exists as a diatomic gas and makes up approximately 78% of Earth's atmosphere?","options":["Nitrogen","Oxygen","Hydrogen","Chlorine"],"answerIndex":0,"answer":null,"explanation":["Nitrogen gas (( \text{N}_2 )) is the most abundant gas component in the atmosphere of our planet."],"hint":"The song mentions it is 'all through the air'.","image":null,"video":"https://youtu.be/rz4Dd1I_fX0?si=Ir4GLYwCuCjX4cVu","videoScope":"set","topic":"Elements of the Periodic Table","classLevel":"grade10","scheme":"practice","subject":"chemistry","subjectLabel":"Chemistry","grade":"Grade 10"},{"id":"sBdbG9trd1H5mitL7fNp","type":"polar","question":"Elements with atomic numbers 57 through 71 represent a unique section where the table splits, known as the Lanthanides.","options":["True","False"],"answerIndex":0,"answer":null,"explanation":["The lanthanide series is pulled out below the main body of the periodic table along with actinides to maintain readability."],"hint":"Listen to the lyric 'and this is where the table splits where lanthanides have just begun'.","image":null,"video":"https://youtu.be/rz4Dd1I_fX0?si=Ir4GLYwCuCjX4cVu","videoScope":"set","topic":"Elements of the Periodic Table","classLevel":"grade10","scheme":"practice","subject":"chemistry","subjectLabel":"Chemistry","grade":"Grade 10"},{"id":"xqeYCmNkbeUZcmxxr4ii","type":"theory","question":"Explain why Group 1 alkali metals and Group 17 halogens both exhibit high reactivity, but for opposite chemical reasons.","options":null,"answerIndex":null,"answer":"Alkali metals have one valence electron which they readily lose to achieve a stable outer shell, whereas halogens have seven valence electrons and aggressively gain one electron to complete their octet.","explanation":["Reactivity depends on electron configuration; Group 1 loses an electron easily, while Group 17 gains one easily."],"hint":"","image":null,"video":"https://youtu.be/rz4Dd1I_fX0?si=Ir4GLYwCuCjX4cVu","videoScope":"set","topic":"Elements of the Periodic Table","classLevel":"grade10","scheme":"practice","subject":"chemistry","subjectLabel":"Chemistry","grade":"Grade 10"},{"id":"yA6jEk7RpJzmCBfKnQDR","type":"polar","question":"Oxygen is listed before fluorine in Period 2 because oxygen has a smaller atomic number.","options":["True","False"],"answerIndex":0,"answer":null,"explanation":["Oxygen has an atomic number of 8, and Fluorine has 9. The table is ordered sequentially by atomic number."],"hint":"Recall the sequence order of elements from the song.","image":null,"video":"https://youtu.be/rz4Dd1I_fX0?si=Ir4GLYwCuCjX4cVu","videoScope":"set","topic":"Elements of the Periodic Table","classLevel":"grade10","scheme":"practice","subject":"chemistry","subjectLabel":"Chemistry","grade":"Grade 10"}];
